/* global process */
// Resolve resources/chatgpt-web/current/*.js → generated filename map.
// Run after swapping reference bundles. npm test and build.mjs call this.

import { writeFileSync } from 'node:fs'
import { dirname, join, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'
import { CHATGPT_WEB_SPEC_TEMPLATE } from '../src/services/protocol-probe/specs.mjs'
import { resolveChatgptWebCurrentReference } from '../src/services/protocol-probe/resolve-chatgpt-web-reference.mjs'

const repoRoot = join(dirname(fileURLToPath(import.meta.url)), '..')

export function syncProtocolReference(root = repoRoot) {
  const reference = resolveChatgptWebCurrentReference({
    repoRoot: root,
    spec: CHATGPT_WEB_SPEC_TEMPLATE,
  })
  const quote = (value) => `'${String(value).replace(/\\/g, '\\\\').replace(/'/g, "\\'")}'`
  const files = reference.files
    .map(
      (file) => `    {
      filename: ${quote(file.filename)},
      roleId: ${quote(file.roleId)},
    }`,
    )
    .join(',\n')
  const body = `// Generated by scripts/sync-protocol-reference.mjs — do not edit.
// Source of truth: resources/chatgpt-web/current/*.js

export default {
  dir: ${quote(reference.dir)},
  files: [
${files},
  ],
}
`
  writeFileSync(join(root, 'src/services/protocol-probe/chatgpt-web-current.mjs'), body)
  return reference
}

if (process.argv[1] && fileURLToPath(import.meta.url) === resolve(process.argv[1])) {
  const reference = syncProtocolReference()
  console.log(
    `Synced ${reference.files.length} files from ${reference.dir}:`,
    reference.files.map((file) => `${file.roleId}=${file.filename}`).join(', '),
  )
}
